/** A whole STATUS message (kind 9); section counts are derived. */
export interface StatusBlock {
  currentFrame: number;
  dateMs: number;
  pingSeq: number;
  pingFrameLo: number;
  underruns: number;
  lateCommands: number;
  workUnits: number;
  workUnitsMax: number;
  mixedVoices: number;
  liveVoices: number;
  flags: number;
  mixedCap: number;
  loadPermille: number;
  traps: number;
  minSlackFrames: number;
  underrunFrames: number;
  arenaUsedKB: number;
  arenaLargestFreeKB: number;
  abiVersion: number;
  maxLatenessFrames: number;
  hrtfVoices: number;
  hrtfLoadFailure: number;
  /** voices that ended in this block (at most 1024 per block) */
  ended: number[];
  /** voices virtualised by the adaptive cap (at most 1024 per block) */
  demoted: number[];
  /** voices that starved this block; the rest carry over (at most 1024 per block) */
  starved: number[];
  /** playheads of looping, streamed and long clips, round-robin (at most 256 per block) */
  playheads: StatusPlayheadsItem[];
  /** ClipEvent codes: 1 resident, 2 refusedCeiling, 3 refusedGrow, 4 hrtfReady (at most 64 per block) */
  clipEvents: StatusClipEventsItem[];
  /** StreamEvent codes: 1 starved, 2 eos, 3 error (at most 64 per block) */
  streamEvents: StatusStreamEventsItem[];
  /** peak level per bus, left and right (at most 32 per block) */
  peaks: StatusPeaksItem[];
}

/** Write a whole STATUS message at `off` (envelope first); returns the bytes written. */
export function writeStatus(view: DataView, off: number, rec: StatusBlock, seq: number): number {
  view.setFloat64(off + 16, rec.currentFrame, true);
  view.setFloat64(off + 24, rec.dateMs, true);
  view.setUint32(off + 32, rec.pingSeq, true);
  view.setUint32(off + 36, rec.pingFrameLo, true);
  view.setUint32(off + 40, rec.underruns, true);
  view.setUint32(off + 44, rec.lateCommands, true);
  view.setUint32(off + 48, rec.workUnits, true);
  view.setUint32(off + 52, rec.workUnitsMax, true);
  view.setUint16(off + 56, rec.mixedVoices, true);
  view.setUint16(off + 58, rec.liveVoices, true);
  view.setUint32(off + 60, rec.flags, true);
  if (rec.ended.length > 1024) throw new WireError(ErrorCode.OVERSIZE, "STATUS: ended over its cap 1024");
  view.setUint16(off + 64, rec.ended.length, true);
  if (rec.demoted.length > 1024) throw new WireError(ErrorCode.OVERSIZE, "STATUS: demoted over its cap 1024");
  view.setUint16(off + 66, rec.demoted.length, true);
  if (rec.starved.length > 1024) throw new WireError(ErrorCode.OVERSIZE, "STATUS: starved over its cap 1024");
  view.setUint16(off + 68, rec.starved.length, true);
  if (rec.playheads.length > 256) throw new WireError(ErrorCode.OVERSIZE, "STATUS: playheads over its cap 256");
  view.setUint16(off + 70, rec.playheads.length, true);
  if (rec.peaks.length > 32) throw new WireError(ErrorCode.OVERSIZE, "STATUS: peaks over its cap 32");
  view.setUint16(off + 72, rec.peaks.length, true);
  if (rec.clipEvents.length > 64) throw new WireError(ErrorCode.OVERSIZE, "STATUS: clipEvents over its cap 64");
  view.setUint16(off + 74, rec.clipEvents.length, true);
  if (rec.streamEvents.length > 64) throw new WireError(ErrorCode.OVERSIZE, "STATUS: streamEvents over its cap 64");
  view.setUint16(off + 76, rec.streamEvents.length, true);
  view.setUint16(off + 78, rec.mixedCap, true);
  view.setUint16(off + 80, rec.loadPermille, true);
  view.setUint16(off + 82, rec.traps, true);
  view.setInt32(off + 84, rec.minSlackFrames, true);
  view.setUint32(off + 88, rec.underrunFrames, true);
  view.setUint32(off + 92, rec.arenaUsedKB, true);
  view.setUint32(off + 96, rec.arenaLargestFreeKB, true);
  view.setUint32(off + 100, rec.abiVersion, true);
  view.setUint32(off + 104, rec.maxLatenessFrames, true);
  view.setUint16(off + 108, rec.hrtfVoices, true);
  view.setUint16(off + 110, rec.hrtfLoadFailure, true);
  let cur = off + 112;
  for (const v of rec.ended) {
    view.setUint32(cur, v, true);
    cur += 4;
  }
  for (const v of rec.demoted) {
    view.setUint32(cur, v, true);
    cur += 4;
  }
  for (const v of rec.starved) {
    view.setUint32(cur, v, true);
    cur += 4;
  }
  for (const v of rec.playheads) cur += writeStatusPlayheadsItem(view, cur, v);
  for (const v of rec.clipEvents) cur += writeStatusClipEventsItem(view, cur, v);
  for (const v of rec.streamEvents) cur += writeStatusStreamEventsItem(view, cur, v);
  for (const v of rec.peaks) cur += writeStatusPeaksItem(view, cur, v);
  writeEnvelope(view, off, { kind: Kind.STATUS, seq, bodyBytes: cur - off - 16 });
  return cur - off;
}

/** Read a whole STATUS message; the buffer's first byte is the envelope. */
export function readStatus(buf: ArrayBuffer | ArrayBufferView): StatusBlock {
  const view = buf instanceof ArrayBuffer ? new DataView(buf) : new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const off = 0;
  if (112 > view.byteLength) throw new WireError(ErrorCode.TRUNCATED, "STATUS: truncated");
  const env = readEnvelope(view, 0);
  if (env.magic !== MAGIC) throw new WireError(ErrorCode.BAD_MAGIC, "STATUS: bad magic");
  if (((env.version ?? 0) >> 8) !== VERSION_MAJOR) throw new WireError(ErrorCode.VERSION_MISMATCH, "STATUS: version mismatch");
  if (env.kind !== Kind.STATUS) throw new WireError(ErrorCode.MALFORMED, "STATUS: wrong kind");
  const limit = 16 + env.bodyBytes;
  if (limit > view.byteLength || limit < 112) throw new WireError(ErrorCode.TRUNCATED, "STATUS: truncated");
  const currentFrame = view.getFloat64(off + 16, true);
  const dateMs = view.getFloat64(off + 24, true);
  const pingSeq = view.getUint32(off + 32, true);
  const pingFrameLo = view.getUint32(off + 36, true);
  const underruns = view.getUint32(off + 40, true);
  const lateCommands = view.getUint32(off + 44, true);
  const workUnits = view.getUint32(off + 48, true);
  const workUnitsMax = view.getUint32(off + 52, true);
  const mixedVoices = view.getUint16(off + 56, true);
  const liveVoices = view.getUint16(off + 58, true);
  const flags = view.getUint32(off + 60, true);
  const endedCount = view.getUint16(off + 64, true);
  const demotedCount = view.getUint16(off + 66, true);
  const starvedCount = view.getUint16(off + 68, true);
  const playheadCount = view.getUint16(off + 70, true);
  const busCount = view.getUint16(off + 72, true);
  const clipEventCount = view.getUint16(off + 74, true);
  const streamEventCount = view.getUint16(off + 76, true);
  const mixedCap = view.getUint16(off + 78, true);
  const loadPermille = view.getUint16(off + 80, true);
  const traps = view.getUint16(off + 82, true);
  const minSlackFrames = view.getInt32(off + 84, true);
  const underrunFrames = view.getUint32(off + 88, true);
  const arenaUsedKB = view.getUint32(off + 92, true);
  const arenaLargestFreeKB = view.getUint32(off + 96, true);
  const abiVersion = view.getUint32(off + 100, true);
  const maxLatenessFrames = view.getUint32(off + 104, true);
  const hrtfVoices = view.getUint16(off + 108, true);
  const hrtfLoadFailure = view.getUint16(off + 110, true);
  let cur = 112;
  if (endedCount > 1024 || endedCount * 4 > limit - cur) throw new WireError(ErrorCode.OVERSIZE, "STATUS: ended overrun");
  const ended: number[] = [];
  for (let i = 0; i < endedCount; i++) {
    ended.push(view.getUint32(cur, true));
    cur += 4;
  }
  if (demotedCount > 1024 || demotedCount * 4 > limit - cur) throw new WireError(ErrorCode.OVERSIZE, "STATUS: demoted overrun");
  const demoted: number[] = [];
  for (let i = 0; i < demotedCount; i++) {
    demoted.push(view.getUint32(cur, true));
    cur += 4;
  }
  if (starvedCount > 1024 || starvedCount * 4 > limit - cur) throw new WireError(ErrorCode.OVERSIZE, "STATUS: starved overrun");
  const starved: number[] = [];
  for (let i = 0; i < starvedCount; i++) {
    starved.push(view.getUint32(cur, true));
    cur += 4;
  }
  if (playheadCount > 256 || playheadCount * 8 > limit - cur) throw new WireError(ErrorCode.OVERSIZE, "STATUS: playheads overrun");
  const playheads: StatusPlayheadsItem[] = [];
  for (let i = 0; i < playheadCount; i++) {
    playheads.push(readStatusPlayheadsItem(view, cur));
    cur += 8;
  }
  if (clipEventCount > 64 || clipEventCount * 8 > limit - cur) throw new WireError(ErrorCode.OVERSIZE, "STATUS: clipEvents overrun");
  const clipEvents: StatusClipEventsItem[] = [];
  for (let i = 0; i < clipEventCount; i++) {
    clipEvents.push(readStatusClipEventsItem(view, cur));
    cur += 8;
  }
  if (streamEventCount > 64 || streamEventCount * 8 > limit - cur) throw new WireError(ErrorCode.OVERSIZE, "STATUS: streamEvents overrun");
  const streamEvents: StatusStreamEventsItem[] = [];
  for (let i = 0; i < streamEventCount; i++) {
    streamEvents.push(readStatusStreamEventsItem(view, cur));
    cur += 8;
  }
  if (busCount > 32 || busCount * 8 > limit - cur) throw new WireError(ErrorCode.OVERSIZE, "STATUS: peaks overrun");
  const peaks: StatusPeaksItem[] = [];
  for (let i = 0; i < busCount; i++) {
    peaks.push(readStatusPeaksItem(view, cur));
    cur += 8;
  }
  return { currentFrame, dateMs, pingSeq, pingFrameLo, underruns, lateCommands, workUnits, workUnitsMax, mixedVoices, liveVoices, flags, mixedCap, loadPermille, traps, minSlackFrames, underrunFrames, arenaUsedKB, arenaLargestFreeKB, abiVersion, maxLatenessFrames, hrtfVoices, hrtfLoadFailure, ended, demoted, starved, playheads, clipEvents, streamEvents, peaks };
}
